// ── IntakeQ Integration ───────────────────────────────────────────────────────
const INTAKEQ_WORKER = 'https://spark-intakeq.ilikebroccoli.workers.dev';
const intakeQCache = {};

async function fetchIntakeQAppointments(date) {
  if (intakeQCache[date] && Date.now() - intakeQCache[date].ts < 5*60*1000) return intakeQCache[date].data;
  try {
    const res = await fetch(`${INTAKEQ_WORKER}/forms?date=${date}`);
    if (!res.ok) return [];
    const data = await res.json();
    intakeQCache[date] = { data: Array.isArray(data)?data:[], ts: Date.now() };
    return intakeQCache[date].data;
  } catch { return []; }
}

function matchIntakeQAppointment(patientName, date, forms) {
  if (!forms?.length || !patientName) return null;
  const parts = patientName.split(',').map(s=>s.trim().toLowerCase());
  const billingLast = parts[0]||'';
  const billingFirst = (parts[1]||'').split(/\s+/)[0];
  let best=null, bestScore=0;
  for (const form of forms) {
    const words=(form.ClientName||'').trim().toLowerCase().split(/\s+/);
    const intakeLast=words[words.length-1]||'';
    const intakeFirst=words[0]||'';
    if(!billingLast||!intakeLast||intakeLast!==billingLast) continue;
    const firstOk=billingFirst&&intakeFirst?intakeFirst.slice(0,2)===billingFirst.slice(0,2):true;
    if(!firstOk) continue;
    const firstMatch=intakeFirst.startsWith(billingFirst)||billingFirst.startsWith(intakeFirst)?1:0.7;
    const formDate=form.DateSubmitted?new Date(form.DateSubmitted).toISOString().slice(0,10):'';
    const daysDiff=formDate?Math.abs((new Date(date)-new Date(formDate))/86400000):99;
    const dateScore=daysDiff<=14?1-daysDiff/28:0;
    const score=firstMatch*0.7+dateScore*0.3;
    if(score>bestScore){bestScore=score;best=form;}
  }
  return best;
}

