function shortRetinal(answer) {
  if (!answer) return null;
  const a = answer.toLowerCase();
  if (a.includes('declin')) return 'Declined';
  if (a.includes('bundle') || (a.includes('oct') && a.includes('retinal'))) return 'Optomap + OCT';
  if (a.includes('$40') || a.includes('3 minutes') || a.includes('option 1') || a.includes('retinal imaging')) return 'Optomap';
  if (a.includes('dilat')) return 'Dilation';
  return answer.slice(0, 25) + (answer.length > 25 ? '…' : '');
}

